/* Месяцеслов «Православных» — 04.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M04: SaintRec[] = [
  { key: "04-01", name: "прав. Софии, княгини Слуцкой", kind: "saint", desc: "Святая праведная София, княжна, а затем княгиня Слуцкая, происходила из древнего рода Олельковичей, княживших в городе Слуцке, одном из древнейших городов Северо-Западной Руси." },
  { key: "04-01", name: "прп. Симеона Псково-Печерского, иеросхимонаха", kind: "saint", desc: "Преподобный Симеон (в миру Василий Иванович Желнин) родился 1 марта 1869 года в деревне Яковлевской Островского уезда Псковской губернии в крестьянской семье от родителей Иоанна и Наталии." },
  { key: "04-01", name: "Прп. Иннокентия Комельского, Вологодского", kind: "saint", desc: "Преподобный Иннокентий Комельский, Вологодский, родился в Москве и происходил от рода московских князей Охлябининых. Он принял монашество в монастыре преподобного Кирилла Белозерского (&dagger; 9 июня 1427 года) и был отдан в руководство преподобному Нилу Сорскому (&dagger; 1508, память 7 мая)." },
  { key: "04-01", name: "мч. Панхария Римского", kind: "saint", desc: "Святой мученик Панхарий был сановником императора Максимиана (305–311). Он оставил христианство и стал язычником. Мать и сестра, узнав об этом, прислали ему письмо, в котором убеждали отступника исполниться страха Божия и вспомнить о будущем Суде." },
  { key: "04-01", name: "прп. Вассы Псково-Печерской", kind: "saint", desc: "В 1472 году крестьянин Иван Дементьев рубил лес на обрыве горы. Одно из срубленных деревьев покатилось вниз, сдирая землю и вырывая с корнем другие деревья." },
  { key: "04-01", name: "прп. Симеона Дайбабского (1941)", kind: "saint", desc: "От нашей ревности к вере и от того, как мы служим Богу, зависит наше спасение, наше место в вечности, в пакибытии, да и наша теперешняя жизнь. Смирение в наших поступках и словах способствует Божиему благоволению к нам и излиянию на нас благодати для поддержания нас на благом пути." },
  { key: "04-01", name: "Иоанна Блинова исп.", kind: "saint", desc: "Исповедник Иоанн родился в 1874 году в селе Красное Шуйского уезда Владимирской губернии в семье крестьянина Михаила Блинова. В 1886 году Иван окончил школу в селе Красном, а затем вместе с отцом занимался крестьянским хозяйством." },
  { key: "04-01", name: "прмц. Матроны (Алексеевой), монахини", kind: "saint", desc: "Преподобномученица Матрона родилась в 1862 году в деревне Замятино Зубцовского уезда Тверской губернии в семье крестьянина Иакова Алексеева. Поступив в Новодевичий монастырь в Москве, она прожила в нем до его закрытия при советской власти.", lifeId: "matrona" },
  { key: "04-01", name: "Умиление Смоленская", year: "1103", kind: "saint", desc: "Смоленская икона Божией Матери, именуемая «Умиление», явилась в 1103 году в Смоленске . Этот образ, сыгравший особую, вдохновляющую роль в период обороны Смоленска от польских захватчиков в начале XVII века (1609–1611 гг.), находился в лаге" },
  { key: "04-01", name: "Умиление Ростовская", year: "1911", kind: "saint", desc: "Икона была прославлена как местночтимая святыня 19 марта/1 апреля 1911 г. архиепископом ярославским и ростовским Тихоном (Белавиным), который лично возглавил эти торжества." },
  { key: "04-02", name: "Прп. Евфросина Синозерского, Новгородского", kind: "saint", desc: "Преподобный Евфросин Синозерский, в миру Ефрем, родился в Карелии близ Ладожского озера. В юные годы он жил при Валаамском монастыре, затем переселился в Новгород Великий." },
  { key: "04-02", name: "свт. Никиты исп., архиепископа Аполлониадского", kind: "saint", desc: "Святой Никита Исповедник, архиепископ Аполлониадский, отличался глубоким знанием Священного Писания, был благочестивым и милосердным человеком. В царствование императора-иконоборца Льва Армянина (813–820) он твердо стоял за почитание святых икон, был сослан и скончался в заточении." },
  { key: "04-02", name: "Сщмч. Владимира Пиксанова, пресвитера", kind: "saint", desc: "Новомученик иерей Владимир происходил из рода Пиксановых, несколько поколений которого посвятили свою жизнь служению Богу. Его прадед, Филипп Архангельский, был дьячком в селе Пиксановка Кузнецкого уезда Саратовской губернии." },
  { key: "04-02", name: "сщмч. Василия Соколова, диакона", kind: "saint", desc: "Священномученик Василий родился в 1879 году в селе Сабурово Сергиевской волости Дмитровского уезда Московской губернии в семье диакона Николая Соколова." },
  { key: "04-03", name: "Прп. Иакова исп., епископа Катанского", kind: "saint", desc: "Преподобный Иаков, епископ и исповедник, с юных лет стремился к подвижнической жизни. Святой Иаков оставил мир и удалился в Студийский монастырь, где принял монашество." },
  { key: "04-03", name: "прп. Серафима Вырицкого", kind: "saint", desc: "Преподобный Серафим Вырицкий (в миру Василий Николаевич Муравьев) родился 31 марта 1866 года в деревне Вахромеево Рыбинского уезда Ярославской губернии в семье крестьян Николая и Хионии." },
  { key: "04-03", name: "Свт. Кирилла, епископа Катанского", kind: "saint", desc: "Святитель Кирилл родился в Антиохии. Он был учеником апостола Петра (память 29 июня, 16 января), который поставил его во епископа города Катаны в Сицилии." },
  { key: "04-03", name: "свт. Фомы, патриарха Константинопольского", kind: "saint", desc: "Святитель Фома, патриарх Константинопольский, был диаконом, а затем, при святом патриархе Иоанне IV Постнике (582–595), сакелларием (ризничим) в Великой Константинопольской церкви." },
  { key: "04-03", name: "Сщмч. Владимира Введенского, пресвитера", kind: "saint", desc: "Священномученик Владимир родился в 1869 году в городе Шуе Владимирской губернии в семье псаломщика Федора Введенского. В 1889 году он окончил Духовную семинарию и женился на девице Софии." },
  { key: "04-04", name: "Воскрешение прав. Лазаря", kind: "saint", desc: "Св. праведный Лазарь, друг Христов, жил в Вифании с сёстрами Марфой и Марией. Господь Иисус Христос воскресил его из мёртвых на четвертый день после погребения, что стало величайшим чудом." },
  { key: "04-04", name: "Сщмч. Василия, пресвитера Анкирского", kind: "saint", desc: "Священномученик Василий был пресвитером в Анкире Галатийской. Во время широкого распространения арианской ереси он призывал свою паству твердо держаться Православия." },
  { key: "04-04", name: "Мц. Дросиды Римской, дщери царя Траяна", kind: "saint", desc: "Святая мученица Дросида была дочерью императора Траяна (98–117), жестокого гонителя христиан. В 99 году он возобновил существовавший ранее закон, запрещавший тайные общества и косвенно касавшийся христиан, а в 104 году издал специальный закон против христиан." },
  { key: "04-04", name: "прп. Исаакия, игумена Далматского", kind: "saint", desc: "Св. Исаакий Далматский жил в IV веке, был монахом и основателем Далматского монастыря под Константинополем. Прославился обличением ереси арианства и смелым противостоянием императору-еретику Валенту." },
  { key: "04-05", name: "Вход Господень в Иерусалим", kind: "great", desc: "«Вербное Воскресенье» – так обычно называют в народе праздник Входа Господня в Иерусалим. Православные христиане спешат в церковь с пучками пушистых верб." },
  { key: "04-05", name: "Прмч. Никона Сицилийского, епископа и 199-ти учеников его", kind: "icon", desc: "Преподобномученик Никон родился в Неаполе. Его отец был язычником, а мать – христианкой. Возмужав, Никон оставался язычником. Он служил воином и отличался необычайной храбростью и силой." },
  { key: "04-05", name: "Прп. Никона, игумена Киево-Печерского", kind: "icon", desc: "Преподобный Никон был первым учеником и сподвижником преподобного Антония (память 10 июля), основателя Киево-Печерской обители, к которому пришел, уже будучи иереем." },
  { key: "04-05", name: "мч. Василия Мангазейского", kind: "saint", desc: "Святой праведный мученик Василий Мангазейский чудотворец – первый святой, прославленный на Сибирской земле. Блаженный Василий родился около 1583 года в Ярославле, в семье благочестивого, но небогатого горожанина, именем Феодора." },
  { key: "04-05", name: "Сщмч. Константина Снятиновского, пресвитера", kind: "saint", desc: "Священномученик Константин родился в 1865 году, в семье Петра Снятиновского, диакона Храма Казанской иконы Божией Матери Борисо-Глебского погоста Баглачевской волости Владимирского уезда (ныне село Борисоглеб Судогодского района Владимирской области)." },
  { key: "04-05", name: "сщмч. Макария Квиткина, пресвитера", kind: "saint", desc: "Священномученик Макарий родился в 1882 году в городе Орске Оренбургской губернии в семье крестьянина Федора Квиткина. Окончив учительскую семинарию, Макарий несколько лет работал учителем в сельских школах в Орском уезде." },
  { key: "04-05", name: "сщмч. Стефана Преображенского, пресвитера", kind: "saint", desc: "Священномученик Стефан родился 23 марта 1860 года в Юрьевецком уезде Костромской губернии в семье диакона Михаила Преображенского. Стефан окончил Духовную семинарию и был рукоположен во священника." },
  { key: "04-05", name: "сщмч. Василия Коклина, пресвитера", kind: "saint", desc: "Священномученик Василий родился 20 января 1883 года в Москве в семье купца Павла Коклина, владельца посудохозяйственного магазина. Окончив четырехклассное городское училище, он стал помогать отцу." },
  { key: "04-05", name: "прмч. Илии (Вятлина), иеромонаха", kind: "saint", desc: "Преподобномученик Илия родился 24 февраля 1867 года в селе Каринское Александровского уезда Владимирской губернии в семье крестьянина Ивана Вятлина, воспитавшего сына в вере и благочестии." },
  { key: "04-05", name: "прмцц. Анастасии Бобковой", kind: "saint", desc: "Преподобномученица Анастасия родилась 16 декабря 1890 года в селе Кузяево Волоколамского уезда Московской губернии в семье крестьянина Степана Бобкова." },
  { key: "04-05", name: "Варвары Конкиной", kind: "saint", desc: "Варвара Ивановна Конкина родилась в 1868 году в деревне Сушки Кирицкой волости Спасского уезда Рязанской губернии в крестьянской семье. В 1887 году, девятнадцатилетней девушкой, она поступила послушницей в Спасо-Влахернский женский монастырь Дмитровского уезда Московской губернии." },
  { key: "04-05", name: "мч. Алексия Скоробогатова", kind: "saint", desc: "Мученик Алексий родился в 1889 году в селе Середниково Волоколамского уезда Московской губернии в семье крестьянина Семена Скоробогатова. Получив начальное образование, Алексей был назначен учителем в церковноприходскую школу в селе Воронцово Рузского уезда." },
  { key: "04-05", name: "прп. Сергия (Сребрянского) исп., архимандрита", kind: "saint", desc: "Исповедник Сергий родился 1 августа 1870 года в селе Трехсвятском Воронежского уезда Воронежской губернии в семье священника Василия Сребрянского и в крещении был наречен Митрофаном." },
  { key: "04-06", name: "Прп. Захарии Отверстого, монаха", kind: "saint", desc: "Преподобный Захария монах за свое особое попечение о нищих и странниках был прозван \"отверстым\". В печатной Минее его память обозначена как \"преподобного отца нашего Захарии\" – отсюда ошибочное разделение в месяцеслове Захарии и преподобного Захарии монаха." },
  { key: "04-06", name: "свт. Артемия (Артемона), епископа Солунского (Селевкийского)", kind: "saint", desc: "Святитель Артемон, епископ Селевкийский, родился и жил в Селевкии Писидийской (Малая Азия). Он был благочестив и добродетелен, поэтому святой апостол Павел, придя в Селевкию, поставил святого Артемона первым епископом этого города, как наиболее достойного." },
  { key: "04-06", name: "Прп. Захарии, постника Печерского, в Дальних пещерах", kind: "saint", desc: "В монастыре Печерском есть следующее сказание о Захарии, иноке Печерском. Во время игуменства блаженного Никона два мужа киевских, Сергий и Иоанн, однажды, молясь пред явленной чудотворной иконой Пресвятой Богородицы, увидели исходящий от нее великий свет и тотчас положили заключить между собой духовное братство." },
  { key: "04-06", name: "Стефана", kind: "saint", desc: "Родом из татар. Страдал в течении 20 лет расслаблением ног. Уверовав во Христа, получил исцеление и принял Св. Крещение в 1552 г. после взятия Казани Иоанном Грозным." },
  { key: "04-06", name: "Петра Казанских", kind: "saint", desc: "Святой мученик Петр Казанский пострадал вместе с мучеником Стефаном от казанских татар за обращение в христианство из мусульман. Родные после ухода русских войск взяли его силой домой и называли прежним мусульманским именем, надеясь, что он откажется от Христа." },
  { key: "04-06", name: "прп. Иакова исп., епископа Катанского", kind: "saint", desc: "Преподобный Иаков, епископ и исповедник, с юных лет стремился к подвижнической жизни. Святой Иаков оставил мир и удалился в Студийский монастырь, где принял монашество." },
  { key: "04-06", name: "свт. Иринея (Чирича) исп., епископа Бачского (1955)", kind: "saint", desc: "Священноисповедник Ириней (Чирич), епископ Бачский (1884-1955), выпускник Московской духовной академии и Венского университета, видный филолог, богослов и миссионер в годы Второй мировой войны организовал спасение тысяч сербских детей из концлагеря в Венгрии и заступался за паству, защищая ее от карательных акций." },
  { key: "04-06", name: "Сщмч. Александра Флегинского, пресвитера", kind: "saint", desc: "Священник Александр Косьмич Флегинский родился 19 февраля 1861 года в семье священника. По окончании в 1883 году Ставропольской духовной семинарии получил место псаломщика при Казанском соборе города Ставрополя." },
  { key: "04-06", name: "сщмч. Владимира Панькина, пресвитера", kind: "saint", desc: "Священномученик Владимир – священник Владимир Васильевич Панькин – служил в храме в селе Благовещенка, расположенном в районе, в советское время называвшемся Джамбульским, Северо-Казахстанской области." },
  { key: "04-06", name: "Тучная Гора", kind: "saint", desc: "Около 250–300 лет тому назад эта икона находилась в одном из мужских монастырей Твери и подарена была настоятелем Косме Волчанинову в благодарность за хорошо исполненные работы в монастырском храме." },
  { key: "04-07", name: "Благовещение Пресвятой Богородицы", kind: "great", desc: "Название праздника указывает на какое-то особое, неслыханное ранее «радостное известие», прозвучавшее единожды в мировой истории. Этим и объясняется отсутствие у праздника уточняющего смысл подзаголовка (особенно в обиходной речи): произнос" },
  { key: "04-07", name: "Преставление свт. Тихона, патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Тихон (Беллавин, 1865–1925) – одиннадцатый Патриарх Московский и всея Руси. Принял монашество в 1891 году. Управлял епархиями в Северной Америке, Ярославле, Вильно, проявляя особую заботу о пастве." },
  { key: "04-07", name: "прп. Саввы Нового, иеромонаха", kind: "saint", desc: "Святой Савва (мирское имя Василий) родился в 1862 году в селении Ираклица области Восточная Фракия. Его родители были бедными и простыми людьми. Звали их Константин и Смарагда." },
  { key: "04-07", name: "Благовещение Киевская", kind: "great", desc: "В Киево-Софийском соборе , на восточных столбах, поддерживающих алтарную арку, можно увидеть мозаичное изображение архангела Гавриила и Богоматери, образующих композицию «Благовещение»." },
  { key: "04-07", name: "Благовещение Московская", kind: "great", desc: "Хотя торжественное празднование дня Благовещения началось в IV веке, но иконы, отображающие это событие, появились в христианской церкви несравненно раньше." },
  { key: "04-08", name: "Собор Архангела Гавриила", kind: "feast", desc: "Архангел Гавриил – один из главных вестников Божиих в истории спасения человечества. Именно он принёс Деве Марии Благую весть о рождении Сына Божьего – Иисуса Христа." },
  { key: "04-08", name: "Сщмч. Иринея, епископа Сирмийского (Сремского)", kind: "saint", desc: "Священномученик Ириней пострадал во время гонения на христиан при римских императорах Диоклитиане и Максимиане (284–305). Он был пресвитером, вместе с женой воспитывал детей в христианском благочестии и пользовался большим уважением за свою" },
  { key: "04-08", name: "прп. Малха Сирийского", kind: "saint", desc: "Преподобный Малх был единственным сыном земледельца, жившего неподалеку от Антиохии Сирийской. По достижении совершеннолетия родители стали принуждать его жениться, но Малх тайно удалился из родительского дома и принял монашеский постриг в одном из монастырей, где проходил послушание в течение многих лет." },
  { key: "04-08", name: "прп. Василия Нового, Константинопольского", kind: "saint", desc: "Преподобный Василий в молодости оставил мир и подвизался в пустынном месте. Однажды его, обросшего, в рубище, увидели проезжавшие мимо придворные византийского императора и были встревожены его странным видом." },
  { key: "04-08", name: "Мц. Параскевы Кочневой", kind: "saint", desc: "Мученица Параскева родилась в 1890 году в селе Кочнево Оренбургской губернии в семье крестьянина Степана Кочнева. Она окончила сельскую школу, жила с родителями и во время гонений на Русскую Православную Церковь прислуживала при храме в родном селе." },
  { key: "04-09", name: "Мц. Матроны Солунской (Фессалоникийской)", kind: "saint", desc: "Святая Матрона была служанкой знатной еврейки по имени Пантилла, жены командующего императорскими войсками в городе Фессалонике. Матрона почитала Иисуса Христа как истинного Бога и молилась ему втайне, не привлекая внимания госпожи.", lifeId: "matrona" },
  { key: "04-09", name: "прп. Иоанна Прозорливого, Египетского", kind: "saint", desc: "Преподобный Иоанн Прозорливый Египетский (Ликопольский) родился в начале IV века, жил в городе Ликополе (Средний Египет) и был плотником. В возрасте двадцати пяти лет он ушел в монастырь, где принял монашеский постриг." },
  { key: "04-10", name: "Прп. Илариона Нового, игумена Пеликитского", kind: "saint", desc: "Преподобный Иларион Новый, игумен Пеликитский, с юности посвятил себя служению Богу и много лет провел в затворе. За непорочность и святость жизни он сначала удостоился сана пресвитера, а затем был поставлен игуменом Пеликитского монастыря (близ пролива Дарданеллы)." },
  { key: "04-10", name: "прп. Стефана чудотворца, исп., игумена Триглийского", kind: "saint", desc: "Преподобный Стефан Исповедник, игумен Триглийский, пострадал при императоре-иконоборце Льве Армянине (813–820). С самой юности святой подвижник посвятил свою жизнь Богу и принял монашеский постриг, а потом стал настоятелем Триглийского монастыря, близ Константинополя." },
  { key: "04-10", name: "Прмч. Евстратия Печерского, в Ближних пещерах", kind: "saint", desc: "Преподобномученик Евстратий Печерский родился в XI веке в Киеве в богатой семье. С возрастом он принял монашеский постриг в Киево-Печерском монастыре, раздав свое имение нищим." },
  { key: "04-10", name: "прп. Илариона Псковоезерского, Гдовского", kind: "saint", desc: "Прп. Иларион Псковоезерский, Гдовский, был учеником прп. Евфросина Псковского. В XV веке он избрал для подвижнической жизни уединенное место на берегу реки Желчи близ Чудского озера, где основал Озерский Покровский монастырь (1460 г.)." },
  { key: "04-10", name: "мч. Бояна (Енравота), кн. Болгарского", kind: "saint", desc: "Святой мученик Боян, князь Болгарский, пострадал за веру во Христа около 830 года. Когда на болгарский престол вступил его брат-язычник Маломир (Владимир), благоверный князь Боян обратился к нему с просьбой освободить из заточения христиани" },
  { key: "04-10", name: "Св. Николая Постникова исп., пресвитера", kind: "saint", desc: "Священноисповедник Николай родился в 1857 году в городе Касимове Рязанской губернии в семье священника Иакова Постникова. В 1878 году Николай Яковлевич окончил Духовную семинарию и до 1883 года был директором и преподавателем Закона Божия Курловского одноклассного образцового училища в Касимовском уезде." },
  { key: "04-10", name: "сщмч. Василия Малинина, пресвитера", kind: "saint", desc: "Священномученик Василий родился 30 декабря 1877 года в селе Патакино Владимирского уезда Владимирской губернии в семье псаломщика Ксенофонта Малинина. По окончании Владимирской Духовной семинарии он был рукоположен во священника и служил в храме во имя преподобного Корнилия в городе Переславле." },
  { key: "04-10", name: "мч. Иоанна Чернова", kind: "saint", desc: "Мученик Иоанн родился в 1880 году в деревне Алексеевка Рождественской волости Боровского уезда Калужской губернии [1] в семье крестьянина Алексея Чернова." },
  { key: "04-11", name: "Прп. Иоанна Египетского, пустынника", kind: "saint", desc: "Во время гонений на христиан благочестивая вдова Иулиания скрывалась от преследований с двумя малолетними детьми Иоанном и Фимистией. Своих детей она постоянно учила молитвам и чтению Священных Книг." },
  { key: "04-11", name: "свт. Евстафия исп., епископа Кийского (Вифинского)", kind: "saint", desc: "Святитель Евстафий исповедник, епископ Вифинийский, уже в начале подвига был ревностным иноком, кротким и мудрым, исполненным великой веры и любви к ближним." },
  { key: "04-11", name: "Ионы (1480) Псково-Печерских", kind: "saint", desc: "Первым пустынножителем Печерским почитается преподобный Марк, первым же основателем монастыря был преподобный Иона. В древней повести летописец после имени прп." },
  { key: "04-11", name: "Св. Михаила Викторова исп., пресвитера", kind: "saint", desc: "Михаил Иванович Викторов родился в 1871 году в селе Болошнево Рязанского уезда Рязанской губернии в семье протоиерея Иоанна Викторова. Образование будущий священноисповедник получил в Рязанской Духовной семинарии, после окончания которой он был рукоположен к церкви села Болошнева." },
  { key: "04-12", name: "Прп. Иоанна Лествичника, игумена Синайского", kind: "saint", desc: "Преподобный Иоанн Лествичник почитается Святой Церковью как великий подвижник и автор замечательного духовного творения, называемого &quot;Лествицей&quot;, поэтому преподобный и получил прозвание Лествичника." },
  { key: "04-12", name: "свт. Софрония, епископа Иркутского", kind: "saint", desc: "Свт. Софроний (в миру Стефан Кристалевский) родился в 1703 г. в Малороссии. Окончив Киевскую духовную академию, принял монашество в Красногорском монастыре, где ему было видение о будущем епископстве." },
  { key: "04-12", name: "Прор. Иоада, человека Божия", kind: "saint", desc: "Святой пророк Иоад происходил из Самарии и пророчествовал в Х веке до Рождества Христова. О нем повествуется в 13-й главе 3 Книги Царств. Пророк был послан Господом из Иудеи в Вефиль обличить израильского царя Иеровоама за то, что он совратил свой народ в идолопоклонство." },
  { key: "04-12", name: "св. Еввулы Никомидийской, матери вмч. Пантелеимона", kind: "saint", desc: "Святая Еввула, мать великомученика Пантелеимона (память 27 июля), скончалась мирно около 303 года ранее мучений своего сына. Святая Еввула преставилась ко Господу 30 марта около 303 года в г." },
  { key: "04-12", name: "прп. Иоанна Безмолвника (Молчальника), епископа Колонийского", kind: "saint", desc: "Преподобный Иоанн Молчальник (затворник) родился около 454 года в городе Никополе Армянском в семье военачальника Енкратия и супруги его Евфимии. Мальчик рано начал изучать Священное Писание и всем сердцем полюбил уединение и молитву." },
  { key: "04-12", name: "прп. Зосимы, епископа Сиракузского", kind: "saint", desc: "Святитель Зосима, епископ Сиракузский, родился по усердным молитвам благочестивых родителей, долго не имевших детей. Когда сыну исполнилось семь лет, родители отдали его на воспитание в монастырь, где святой подвижник с возрастом принял постриг и сорок лет настоятельствовал в обители." },
  { key: "04-13", name: "Сщмч. Ипатия, епископа Гангрского", kind: "saint", desc: "Священномученик Ипатий, епископ Гангрский, славный чудотворец и целитель. Его жизнь, подвиги и чудотворения, изложенные по древним греческим рукописям В годы царствования равноапостольного императора Константина милость Божья щедро одарила " },
  { key: "04-13", name: "свт. Ионы, митрополита Московского и всея Руси, чудотворца", kind: "saint", desc: "Родился в Костромской земле. Ученик свт. Фотия. Стал первым автокефальным митрополитом, избранным в Москве (1448 г.), без утверждения Константинополя. Способствовал духовному единению Руси, укреплял власть московских князей." },
  { key: "04-13", name: "свт. Иннокентия, митрополита Московского", kind: "saint", desc: "Свт. Иннокентий (в миру Иван Попов-Вениаминов), митрополит Московский (1797-1879) – выдающийся миссионер, просветитель народов Америки и Сибири. За 45 лет он крестил десятки тысяч человек, строил храмы и школы, изучал языки, быт и нравы местных народов." },
  { key: "04-13", name: "Прп. Ипатия целебника, Печерского, в Дальних пещерах", kind: "saint", desc: "Это было тяжкое для Руси время, когда после нашествия полчищ хана Батыя 1240 года «древний Киев исчез на века, ибо сия некогда знаменитая столица, мать градов Российских, в четырнадцатом и пятнадцатом веке представляла еще развалины»." },
  { key: "04-13", name: "прп. Филарета (Данилевского), игумена", kind: "saint", desc: "Прп. Филарет (Данилевский, 1777–1841) – выдающийся подвижник и возобновитель Глинской пустыни. Приняв постриг в Софрониевой пустыни, стяжал дар умной молитвы и духовного рассуждения." },
  { key: "04-13", name: "прп. Аполлония Египетского", kind: "saint", desc: "Преподобный Аполлоний был сыном благочестивых родителей Аиси и Амани. По одной версии, у него был старший брат, монах, умерший до его рождения, который являлся ему во сне; по другим данным, его родители были бездетными до рождения Аполлония." },
  { key: "04-13", name: "Авды, епископа Персидского", kind: "saint", desc: "Святитель Авда был епископом в Персии. За разрушение храма огнепоклонников он был приведен на суд к персидскому царю Издегерду I (401–402), который повелел восстановить храм." },
  { key: "04-13", name: "и Вениамина, диакона", kind: "saint", desc: "Сщмч. Вениамин Персидский пострадал за Христа в V веке. Будучи диаконом, он обратил в христианство многих персов-язычников. После двух лет заключения его освободили при условии прекращения проповеди, но он продолжил своё дело." },
  { key: "04-13", name: "прп. Ипатия, игумена Руфианского", kind: "saint", desc: "Родился во Фригии (Малая Азия) в семье адвоката и получил хорошее образование. Однажды, когда ему было восемнадцать лет, отец наказал его, после чего юноша покинул дом и ушел во Фракию (Балканы)." },
  { key: "04-13", name: "Сщмч. Иоанна Блюмовича, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился в 1888 году в Варшаве в семье рабочего Александра Блюмовича. В 1918 году Иван Александрович переехал с женой в Москву. Вскоре он был рукоположен во священника." },
  { key: "04-14", name: "Иверской иконы Божией Матери", kind: "icon", desc: "Иверская икона Божией Матери, находящаяся на Афоне , прославилась многими чудесами. Слух о чудотворном образе через паломников распространился по России." },
  { key: "04-14", name: "Прп. Марии Египетской", kind: "saint", desc: "Преподобная Мария, прозванная Египетской, жила в середине V и в начале VI столетия. Ее молодость не предвещала ничего хорошего. Марии исполнилось лишь двенадцать лет, когда она ушла из своего дома в городе Александрии." },
  { key: "04-14", name: "прп. Евфимия, архимандрита Суздальского, чудотворца", kind: "saint", desc: "Прп. Евфимий Суздальский (1316–1404) с детства отличался благочестием, усердно изучал Св. Писание. Приняв монашество в Нижегородском Печерском монастыре, исполнял тяжелые послушания, проводя ночи в молитвах." },
  { key: "04-14", name: "прп. Варсонофия Оптинского", kind: "saint", desc: "Прп. Варсонофий Оптинский (в миру Павел Плиханков, 1845-1913) ‒ великий оптинский старец, бывший военный, принявший монашество в 1900 г. Стал духовным преемником прп." },
  { key: "04-14", name: "Мч. Авраамия Болгарского, Владимирского чудотворца", kind: "saint", desc: "Мученик Авраамий родился в Камской Болгарии (болгары жили между реками Волгою и Камою, впоследствии постепенно утратили свою народность и смешались с победившими их татарами) и воспитан был в магометанской вере, которую исповедовали его соотечественники." },
  { key: "04-14", name: "прп. Геронтия, канонарха Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Геронтий подвизался в XIV веке. Он был иноком Киево-Печерского монастыря и исполнял послушание канонарха. Всю свою жизнь он провел в обители, в подвигах воздержания, послушания и молитвы." },
  { key: "04-14", name: "прп. Макария, игумена Пеликитской обители", kind: "saint", desc: "Прп. Макарий, игумен Пеликитский, родился в Константинополе. Принял монашество в Пеликитской обители под руководством прп. Илариона. После смерти наставника братия избрала Макария игуменом." },
  { key: "04-14", name: "Геронтия", kind: "saint", desc: "Мученики Геронтий и Василид претерпели мученическую смерть за Христа в III веке; их усекли мечом. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Соо" },
  { key: "04-14", name: "Василида", kind: "saint", desc: "Мученики Геронтий и Василид претерпели мученическую смерть за Христа в III веке; их усекли мечом. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку 'Соо" },
  { key: "04-14", name: "прав. Ахаза", kind: "saint", desc: "Время жизни неизвестно. Отождествление с иудейским царём Ахазом возможно, но маловероятно – ввиду известных нечестивых дел последнего. Память праведного Ахаза без жития включена под 1 апреля в греческие рукописные стишные синаксари и печатные Минеи." },
  { key: "04-14", name: "преподобномучеников отцов Давидо-Гареджийских (1616) (Груз.)", kind: "saint", desc: "Преподобномученики отцы Давидо-Гареджийской Лавры, числом более 6000, приняли мученическую кончину в Грузии за исповедание христианской веры в начале XVII века, при шахе Аббасе I." },
  { key: "04-14", name: "Сщмч. Сергия Заварина, пресвитера", kind: "saint", desc: "Священномученик Сергий родился 10 сентября 1885 года в селе Вознесенское Любимского уезда Ярославской губернии в семье священника Константина Заварина." },
  { key: "04-14", name: "Одигитрия Шуйская", year: "1654–1655", kind: "saint", desc: "Шуйская-Смоленская икона – поясное изображение Божией Матери с Младенцем Христом на руках. Спаситель сидит справа на левой руке Богоматери. Иконографической особенностью Шуйской иконы, отличающей ее от других икон Одигитрии, является характ" },
  { key: "04-15", name: "Прп. Тита чудотворца, иеромонаха", kind: "saint", desc: "Преподобный Тит чудотворец жил в конце VIII – начале IX века. С самого раннего детства возлюбил он Господа Иисуса Христа, отвергнув суету мирскую и презрев похоть плоти." },
  { key: "04-15", name: "мч. Поликарпа Александрийского", kind: "saint", desc: "Святой мученик Поликарп пострадал за смелое обличение императора Максимиана (305–313) в пролитии невинной христианской крови в городе Александрии. Он открыто исповедал себя христианином и пошел на добровольные мучения." },
  { key: "04-15", name: "Собор преподобных отцов, на Богошественной Горе Синай подвизавшихся", kind: "feast", desc: "В среду Светлой седмицы Православная Церковь празднует Собор преподобных отцов, на Богошественной Горе Синай подвизавшихся. О Синайском монастыре рассказал настоятель нижегородского храма в честь иконы Божией Матери «Умиление» протоиерей Александр Малафеев: «На полуострове Синай я сподобился побывать дважды." },
  { key: "04-15", name: "Касперовская", kind: "saint", desc: "Касперовская чудотворная икона Божией Матери является великой святыней городов Херсона и Одессы, где она пребывает около шести месяцев в году. Дни принесения ее в Одессу (1 октября), и отшествия ее – в четвертый день Пасхи – стали великими церковными торжествами." },
  { key: "04-16", name: "Прп. Никиты Исповедника, игумена обители Мидикийской", kind: "saint", desc: "Преподобный Никита Исповедник, игумен обители Мидикийской, родился в Кесарии Вифинской (северо-запад Малой Азии) в благочестивой семье. Мать умерла на 8-й день после его рождения, и отец, по имени Филарет, постригся в монахи." },
  { key: "04-16", name: "Мц. Феодосии девы", kind: "saint", desc: "Св. мц. Феодосия Тирская пострадала в 307 году. Во время гонений 17-летняя девушка подошла к христианским узникам в претории в Пасхальный день, прося помянуть её перед Господом." },
  { key: "04-16", name: "прп. Иллирика Марсионского", kind: "saint", desc: "Преподобный Иллирик чудотворец подвизался на горе Марсион в Пелопоннесе. Время жизни и подвигов неизвестно. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите к" },
  { key: "04-16", name: "Неувядаемый Цвет", kind: "saint", desc: "На иконе Пресвятая Богородица держит Своего Божественного Сына на одной руке, а в другой руке у Нее – цветок белой лилии. Этот цветок символически знаменует неувядаемый цвет девства и непорочности Пречистой Девы, к Которой так и обращается Святая Церковь: &quot;Ты еси Корень девства и Неувядаемый Цвет чистоты&quot;." },
  { key: "04-17", name: "Иконы Божией Матери Живоносный Источник", kind: "icon", desc: "В V веке в Константинополе, близ так называемых «Золотых ворот», находилась роща, посвященная Пресвятой Богородице. В роще был источник, с давних пор прославленный чудесами." },
  { key: "04-17", name: "Прп. Иосифа Песнописца", kind: "saint", desc: "Преподобный Иосиф Песнописец родился в Сицилии в благочестивой христианской семье. Родители его, Плотин и Агафия, спасаясь от варварского нашествия, переселились в Пелопоннес." },
  { key: "04-17", name: "прп. Георгия, иже в Малеи", kind: "saint", desc: "Преподобный Георгий жил в IX веке. Он был иноком и подвизался в обители на горе Малее в Пелопоннесе, где и скончался. В службе преподобный Георгий ублажается как земной Ангел и чудотворец.", lifeId: "georgiy" },
  { key: "04-17", name: "Прп. Иосифа Многоболезненного, Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Иосиф Многоболезненный жил в XIV веке. В тяжелой болезни он обратился с молитвой к Богу и дал обет: если Господь дарует ему здоровье, то он будет служить братии Киево-Печерского монастыря до конца своей жизни." },
  { key: "04-17", name: "прп. Зосимы Ворбозомского", kind: "saint", desc: "Прп. Зосима Ворбозомский, живший на рубеже XV–XVI веков, основал Благовещенский монастырь на острове Ворбозомского озера под Белозерском. Эта обитель входила в число малых пустынных монастырей «Заволжья», группировавшихся вокруг Кирилло-Белозерского монастыря." },
  { key: "04-17", name: "прп. Зосимы Палестинского, обретшего прп. Марию Египетскую в пустыне Иорданской", kind: "saint", desc: "В одном палестинском монастыре в окрестностях Кесарии жил преподобный инок Зосима. Отданный в монастырь с самого детства, он подвизался в нем до 53 лет, когда был смущен помыслом: &quot;Найдется ли и в самой дальней пустыне святой муж, прев" },
  { key: "04-17", name: "Фервуфы девы, сестры и рабыни ее", kind: "saint", desc: "Святая мученица Фервуфа с ее сестрой и рабыней приняли мученическую смерть за Христа между 341 и 343 годами. Святая Фервуфа и ее сестра, имя которой осталось неизвестным, были родными сестрами епископа Селевкийского Симеона, пострадавшего за Христа при персидском царе Сапоре около 341–344 годов." },
  { key: "04-17", name: "сщмч. Николая (Караулова), епископа Вельского", kind: "saint", desc: "Священномученик Николай родился 28 мая 1871 года в селе Томаш Кадниковского уезда Вологодской губернии в семье священника Аполлония Караулова. В 1893 году Николай окончил Вологодскую Духовную семинарию и был назначен псаломщиком в Георгиевский храм в городе Вологде." },
  { key: "04-17", name: "прмц. Марии Гатчинской, монахини", kind: "saint", desc: "Преподобномученица Мария родилась в 1874 году в Санкт-Петербурге в семье владельца сургучной фабрики, купца Александра Ивановича Лелянова и в крещении была наречена Лидией." },
  { key: "04-17", name: "сщмч. Иоанна Вечорко, пресвитера", kind: "saint", desc: "Священномученик Иоанн родился в 1890 году в селе Косаричи Бобруйского уезда Минской губернии в семье псаломщика Мартина Вечорко. В 1913 году Иван Мартинович окончил Минскую Духовную семинарию и в 1915 году был рукоположен во священника к Покровской церкви в селе Кривоносы, где он и прослужил всю свою жизнь." },
  { key: "04-17", name: "мч. Иоанна Колесникова", kind: "saint", desc: "Мученик Иоанн родился в 1877 году в селе Крылатка Глазовской волости Можайского уезда Московской губернии в семье крестьянина Михаила Колесникова. В 1910 году Иван Михайлович завел колесную мастерскую, в которой работал со своими сыновьями, не привлекая кого-либо из рабочих со стороны." },
  { key: "04-17", name: "Геронтисса", kind: "saint", desc: "На северо-восточном склоне Святой Афонской Горы, на отвесной скале у самого моря находится монастырь Пантократор, основанный в 1361 году греческим императором Алексеем Стратопедархом и братом его Иоанном Примикирием." },
  { key: "04-18", name: "перенесение мощей свт. Иова, патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Иов (†1607), патриарх Московский и всея Руси, родился в г. Старице Тверской губернии. Приняв монашество, прошел путь от послушника до настоятеля Старицкого монастыря." },
  { key: "04-18", name: "Прп. Пуплия Египетского", kind: "saint", desc: "Преподобный Пуплий подвизался в Египетской пустыне во время царствования императора Юлиана Отступника (361–363). Перед военным походом против персов император послал беса проверить путь, по которому ему надлежало идти с войском." },
  { key: "04-18", name: "прп. Марка Афинского, Фраческого", kind: "saint", desc: "Преподобный Марк родился в Афинах. О своей жизни он поведал авве Серапиону, который по воле Божией посетил его перед кончиной. В юности он изучал философию." },
  { key: "04-18", name: "прп. Платона, исп. Студийского", kind: "saint", desc: "Преподобный Платон родился в 735 году в благочестивой христианской семье от родителей Сергия и Евфимии. Рано осиротев, мальчик был взят на воспитание родственниками, которые дали ему хорошее образование." },
  { key: "04-18", name: "прп. Феодоры Солунской (Фессалоникийской)", kind: "saint", desc: "Преподобная Феодора Солунская происходила от христианских родителей Антония и Хрисанфы, живших на острове Эгине. В совершенном возрасте святая Феодора вступила в брак." },
  { key: "04-18", name: "Сщмч. Алексия Кротенкова, пресвитера", kind: "saint", desc: "Священномученик Алексий родился в 1878 году в селе Неклюбка Верещагской волости Суражского уезда Черниговской губернии [1] в семье белорусского крестьянина Петра Кротенкова." },
  { key: "04-18", name: "сщмч. Николая Симо, пресвитера Кронштадтского", kind: "saint", desc: "Священномученик Николай родился 6 декабря 1875 года в городе Аренсбурге Эстляндской губернии в семье священника Адама Симо; в 1888 году отец Адам был назначен в эстонский приход, открывшийся при Андреевском соборе в Кронштадте." },
  { key: "04-19", name: "Свт. Евтихия, архиепископа Константинопольского", kind: "saint", desc: "Святитель Евтихий, архиепископ Константинопольский, родился в селении, носившем название &quot;Божественное&quot;, во Фригийской области. Его отец, Александр, был воином, а мать, Синесия, была дочерью священника августопольской церкви Исихия." },
  { key: "04-19", name: "Равноап. Мефодия, архиепископа Моравского", kind: "saint", desc: "Святые равноапостольные первоучители и просветители славянские, братья Кирилл и Мефодий происходили из знатной и благочестивой семьи, жившей в греческом городе Солуни.", lifeId: "kirill-mefodiy" },
  { key: "04-19", name: "прп. Платониды Сирской", kind: "saint", desc: "Преподобная Платонида первоначально была диакониссой, а затем удалилась в Низибийскую пустыню, где основала женский монастырь. Устав ее обители отличался строгостью." },
  { key: "04-19", name: "мчч. 120-ти Персидских", year: "344–347", kind: "saint", desc: "Святые 120 мучеников пострадали от персидского царя Сапора. Они были взяты в плен персами во время царствования греческого императора Констанция (337–361)." },
  { key: "04-19", name: "прп. Севастиана Карагандинского (Фомина), исп., схиархимандрита", kind: "saint", desc: "Прписп. Севастиан (Фомин) родился в 1884 году. Рано осиротев, он в 1909 году стал келейником прп. Иосифа в Оптиной пустыни, а после его кончины ‒ келейником прп." },
  { key: "04-20", name: "Прп. Георгия исп., митрополита Митиленского", kind: "saint", desc: "Преподобный Георгий, митрополит Митиленский, с юности вел монашеский образ жизни, совершенствуясь преимущественно в добродетели смиренномудрия. В царствование Льва Исаврянина (716–741) святой претерпел гонения от иконоборцев и получил именование Исповедника.", lifeId: "georgiy" },
  { key: "04-20", name: "Прп. Даниила Переяславского, архимандрита", kind: "saint", desc: "Преподобный Даниил Переяславский, в миру Димитрий, родился около 1460 года в городе Переяславле-Залесском от благочестивых Константина и Феодосии (в иночестве Феклы)." },
  { key: "04-20", name: "мч. Каллиопия Помпеопольского", kind: "saint", desc: "Святой мученик Каллиопий родился в Пергии Памфилийской от благочестивой женщины Феоклии, жены знатного сенатора. У Феоклии долгое время не было детей. Она горячо молилась о даровании ей ребенка, обещая посвятить его Богу." },
  { key: "04-20", name: "прп. Серапиона Синдонита, монаха", kind: "saint", desc: "Преподобный Серапион жил в V веке в Египте, назван Синдонитом, потому что носил лишь грубую льняную одежду, называемую синдоном. С самой юности преподобный жил как птица небесная, не имея пристанища, и по несколько дней не ел, не имея на что купить хлеба." },
  { key: "04-20", name: "Сщмч. Аркадия Добронравова, пресвитера", kind: "saint", desc: "Протоиерей Аркадий Добронравов родился в 1868 году в селе Устье Ядринского уезда Казанской губернии (ныне Аликовского района Чувашии) в семье диакона Павла Добронравова." },
  { key: "04-20", name: "прмц. Евдокии Павловой, послушницы", kind: "saint", desc: "Преподобномученица Евдокия – Евдокия Павловна Павлова – родилась 1 августа 1876 года в городе Москве. Когда ей исполнилось одиннадцать лет, ее вместе с сестрой Пелагией, которая была на два года младше, родители отдали на воспитание в Моско" },
  { key: "04-21", name: "Родиона", kind: "saint", desc: "Святые Иродион, Агав, Асинкрит, Руф, Флегонт и Ерм принадлежат к числу 70 апостолов, избранных Христом и посланных им на проповедь (память Собора 70 апостолов 4 января)." },
  { key: "04-21", name: "Асинкрита", kind: "saint", desc: "Святые Иродион, Агав, Асинкрит, Руф, Флегонт и Ерм принадлежат к числу 70 апостолов, избранных Христом и посланных им на проповедь (память Собора 70 апостолов 4 января)." },
  { key: "04-21", name: "Флегонта", kind: "saint", desc: "Святые Иродион, Агав, Асинкрит, Руф, Флегонт и Ерм принадлежат к числу 70 апостолов, избранных Христом и посланных им на проповедь (память Собора 70 апостолов 4 января)." },
  { key: "04-21", name: "Ерма, епископов, и иже с ними", kind: "saint", desc: "Св. апостол Ермий, упомянутый в Рим.16:14, почитается как просветитель Далмации. Согласно церковному преданию, он обращал местных жителей от язычества, совершая чудеса и исцеления." },
  { key: "04-21", name: "Свт. Нифонта Печерского, епископа Новгородского", kind: "saint", desc: "Он был епископом Новгородским и не позволил, чтобы митрополит Киевский был посвящен помимо благословения патриарха Константинопольского; перед смертью видел преподобного Феодосия, обещавшего ему место с собой." },
  { key: "04-21", name: "прп. Руфа, затворника Печерского, в Дальних пещерах", kind: "saint", desc: "Преподобный Руф, затворник Печерский, подвизался в Киево-Печерском монастыре в XIV веке. Он отличался послушанием и прославляется как образец постников и трудолюбцев." },
  { key: "04-21", name: "мч. Павсилипа", kind: "saint", desc: "Святой мученик Павсилип пострадал при императоре Адриане (117–138). По доносу язычников он был приведен на суд к императору и безбоязненно объявил себя христианином." },
  { key: "04-21", name: "свт. Келестина I, папы Римского", kind: "saint", desc: "Святитель Келестин (Целестин), папа Римский (422–432), ревностный поборник Православия, жил во время царствования святого царя Феодосия Младшего (408–450)." },
  { key: "04-21", name: "Сщмч. Сергия Родаковского, пресвитера", kind: "saint", desc: "Священномученик Сергий родился в 1882 году в городе Житковичи Мозырского уезда Минской губернии в семье псаломщика Петра Родаковского. В 1904 году Сергей Петрович окончил Минскую Духовную семинарию, был рукоположен во священника и служил в Успенском храме в селе Лавришево Новогрудского уезда Минской губернии." },
  { key: "04-22", name: "Мч. Евпсихия Кесарийского (Каппадокийского)", kind: "saint", desc: "Святой мученик Евпсихий родился в городе Кесарии Каппадокийской и получил христианское воспитание от своих знатных родителей. Во время царствования Юлиана Отступника (361–363) святой Евпсихий вступил в христианский брак." },
  { key: "04-22", name: "прмч. Вадима, архимандрита", kind: "saint", desc: "Святой преподобномученик Вадим архимандрит родился в IV веке в персидском городе Вифлапате, происходил из богатой и знатной семьи. В молодых годах он был просвещен христианским учением." },
  { key: "04-22", name: "Мч. Гавриила Фомина", kind: "saint", desc: "Гавриил Фомин родился в 1882 году в селе Ивачево Зарайского уезда в семье крестьянина Харитона Фомина. Глубоко верующий человек, Гавриил помогал священнику в храме и исполнял при церкви обязанности сторожа, что было ему по домашним обстоятельствам удобно, так как он был человеком неженатым." },
  { key: "04-23", name: "многих священной обители Пантократора, в Дау Пендели (Аттика) пострадавших", kind: "saint", desc: "Преподобномученики Пантократорской обители [1] в Дау-Пендели пострадали в день Святой Пасхи 1680 года. В то время монастырь был оплотом православия и греческого самосознания в Аттике, здесь собралась многочисленная и ревностная братия, совершавшая непрерывное — «неусыпаемое» — богослужение." },
  { key: "04-23", name: "сщмч. Григория V (Ангелопулоса), патриарха Константинопольского", kind: "saint", desc: "Священномученик Григорий V, патриарх Константинопольский, трижды занимал кафедру (1797–1799, 1806–1808, 1819–1821). В то время Греция находилась под тяжелым турецким игом." },
  { key: "04-23", name: "Сщмч. Флегонта Понгильского, пресвитера", kind: "saint", desc: "Священномученик Флегонт родился 28 марта 1871 года в селе Каряево Угличского уезда Ярославской губернии в семье священника Николая Понгильского. Окончив Ярославскую Духовную семинарию, Флегонт Николаевич стал учителем в церковноприходской ш" },
  { key: "04-23", name: "мч. Димитрия Вдовина", kind: "saint", desc: "Мученик Димитрий родился 3 февраля 1883 года в городе Коломне Московской губернии в семье Михаила Антоновича и Любови Пантелеимовны Вдовиных. Михаил Антонович был мелким торговцем." },
  { key: "04-24", name: "Сщмч. Антипы, епископа Пергама Асийского", kind: "saint", desc: "Священномученик Антипа – ученик святого апостола Иоанна Богослова (память 26 сентября), был епископом Пергамской Церкви в царствование императора Нерона (54–68)." },
  { key: "04-24", name: "Иакова Железноборовского", kind: "saint", desc: "Скудны и недостаточны сведения о преподобном. До нашего времени дошли лишь известия, что преподобный Иаков, мирское имя которого не сохранилось в летописях (существует версия, что он был крещен Иоанном), родился в XIV столетии в благочестивой и весьма достаточной семье галичских дворян Амосовых." },
  { key: "04-24", name: "Иакова Брылеевского, сподвижника его", kind: "saint", desc: "Преподобный Иаков Брылеевский был учеником преподобного Иакова Железноборовского (память 11 апреля) и трудником его монастыря (слово &quot;трудник&quot; имеет два значения: &quot;труженик&quot; и &quot;послушник&quot;)." },
  { key: "04-24", name: "свт. Варсонофия, епископа Тверского", kind: "saint", desc: "Свт. Варсонофий, епископ Тверской, чудотворец Казанский, родился около 1495 года в Серпухове. В юности он 3 года провел в татарском плену, где выучил язык и обычаи." },
  { key: "04-24", name: "прп. Фармуфия Египетского", kind: "saint", desc: "Преподобный Фармуфий жил в IV веке в той же пустыне, где подвизался в студенце (колодце) преподобный Иоанн (память 29 марта), которого питал святой Фармуфий." },
  { key: "04-24", name: "прп. Иоанна Солунского (Фессалоникийского), ученика прп. Григория Декаполита", kind: "saint", desc: "Преподобный Иоанн родился в конце VIII века. В юношеском возрасте он стал учеником преподобного Григория Декаполита (&dagger; ок. 820, память 20 ноября) и принял от него иноческий постриг в Солунском монастыре." },
  { key: "04-24", name: "свт. Каллиника, епископа Черникского (1868)", kind: "saint", desc: "Святитель Каллиник Черникский, епископ Рымникский, в миру Константин, родился в Бухаресте 7 октября 1787 года, в родовитой благочестивой семье Антония и Флоари (в монашестве Филофеи)." },
  { key: "04-24", name: "Сщмч. Николая Гаварина, пресвитера", kind: "saint", desc: "Священномученик Николай родился 23 декабря 1870 года в городе Якобштадте Курляндской губернии в семье священнослужителя Иоанна Гаварина. Николай окончил в 1893 году Рижскую Духовную семинарию по первому разряду и один курс Духовной академии и был рукоположен во священника ко храму в городе Гродно." },
  { key: "04-25", name: "Прп. Василия исп., епископа Парийского", kind: "saint", desc: "Преподобный Василий исповедник, епископ Парийский, жил в VIII веке. Он был избран на епископскую кафедру жителями города Парии, почитавшими святителя как истинного пастыря стада Христова." },
  { key: "04-25", name: "Сщмч. Зинона, епископа Веронийского", kind: "saint", desc: "Священномученик Зинон, епископ Веронийский, был родом грек и происходил из Сирии. С юношеских лет он принял монашество и трудился над изучением Священного Писания." },
  { key: "04-25", name: "прп. Исаака Сирина, в Сполете Италийском", kind: "saint", desc: "Преподобный Исаак Сирин жил в середине VI века. Он пришел в итальянский город Сполето из Сирии. Преподобный попросил разрешения у пономарей остаться в храме и молился в нем двое с половиной суток." },
  { key: "04-25", name: "прп. Анфусы девы", kind: "saint", desc: "Преподобная Анфуса Омонийская родилась 25 января 750 года и была дочерью императора-иконоборца Константина Копронима. После смерти отца она всё своё личное имущество раздала бедным и нищим, а сама приняла монашеский постриг и основала в Константинополе Омонийский монастырь, в котором стала игуменией." },
  { key: "04-25", name: "прп. Афанасии Эгинской, игумении", kind: "saint", desc: "Преподобная Афанасия была игуменией монастыря на острове Эгине. Она родилась в благочестивой христианской семье от супругов Никиты и Марины. Уже в семилетнем возрасте девочка выучила Псалтирь, которую читала постоянно с умилением." },
  { key: "04-25", name: "Прмч. Сергия Крестникова, послушника", kind: "saint", desc: "Преподобномученик Сергий (Сергей Александрович Крестников) родился 1 июля 1893 года в городе Москве. Окончив школу, он в 1905 году поступил в Московский Покровский монастырь и до 1915 года пел здесь в хоре." },
  { key: "04-25", name: "Муромская", year: "XII", kind: "saint", desc: "Муромская икона Божией Матери была принесена в Муром из Киева просветителем этого края святым благоверным князем Константином (&dagger; 1129; память 21 мая)." },
  { key: "04-25", name: "Белыничская", year: "XIII", kind: "saint", desc: "По церковному преданию Белыничская икона Божией Матери была принесена в XIII веке благочестивыми иноками в местечко Белыничи и помещена в Свято-Ильинском храме, где во время всенощного бдения от образа Царицы Небесной чудесным образом воссиял яркий свет." },
  { key: "04-26", name: "Святых жен-мироносиц: Марии Магдалины", kind: "saint", desc: "Св. равноапостольная Мария Магдалина, исцелённая Христом от беснования (Лк.8:2), стала верной последовательницей Спасителя. Она присутствовала при Распятии, погребении и первой удостоилась увидеть Воскресшего Господа (Ин.20:11-18)." },
  { key: "04-26", name: "Марии Клеоповой", kind: "saint", desc: "Святая Мария Клеопова, мироносица, по преданию Церкви была дочерью праведного Иосифа, Обручника Пресвятой Девы Марии, от первого брака и была еще совсем юной, когда Пресвятая Дева Мария была обручена праведному Иосифу и введена в его дом." },
  { key: "04-26", name: "Саломии", kind: "saint", desc: "Родом из Галилеи, жена Зеведея, мать апостолов Иакова и Иоанна. Когда они последовали за Христом, Саломия присоединилась к обществу жен, которые служили Ему." },
  { key: "04-26", name: "Иоанны", kind: "saint", desc: "Св. Иоанна мироносица, жена Хузы ‒ домоправителя царя Ирода, была одной из благочестивых женщин, сопровождавших Христа во время Его земного служения. Она входила в число жен-мироносиц, которые пришли ко гробу Спасителя, чтобы помазать Его т" },
  { key: "04-26", name: "Сусанны и иных", kind: "saint", desc: "О Сусанне упоминает только один евангелист Лука и только однажды: когда рассказывает о прохождении Господа Иисуса Христа по городам и селениям для проповеди и благовествования, то из сопутствующих ему жен именует и Сусанну ( Лк.8:3 ) как служившую Христу от имений своих." },
  { key: "04-26", name: "Иосифа Аримафейского", kind: "saint", desc: "Святой Иосиф Аримафейский был тайным учеником Господа нашего Иисуса Христа. Как член синедриона он не участвовал в &quot;совете и деле&quot; иудеев, вынесших смертный приговор Иисусу Христу." },
  { key: "04-26", name: "Никодима", kind: "saint", desc: "Прав. Никодим, тайный ученик Христа, был фарисеем и членом синедриона. Он защищал Христа перед первосвященниками (Ин.7:50-51) и участвовал в Его погребении (Ин.19:39)." },
  { key: "04-26", name: "Сщмч. Артемона Лаодикийского, пресвитера", kind: "saint", desc: "Священномученик Артемон родился в первой половине III-го века в Лаодикии Сирийской от христианских родителей. С юных лет он посвятил себя служению Церкви." },
  { key: "04-26", name: "Мч. Крискента, из Мир Ликийских", kind: "saint", desc: "Святой мученик Крискент происходил из знатного рода и жил в Мирах Ликийских. Однажды, когда толпа жителей города шла в языческий храм, он стал убеждать их оставить язычество и прийти ко Христу." },
  { key: "04-26", name: "мц. Фомаиды Александрийской (Египетской)", kind: "saint", desc: "Святая мученица Фомаида родилась в городе Александрии в христианской семье. С детства она была воспитана в благочестии и любила читать Священное Писание." },
  { key: "04-26", name: "блгв. Тамары, царицы Грузинской", kind: "saint", desc: "Святая Тамара [1] (1184–1213 гг.), грузинская царица, была дочерью Георгия III от красавицы Бурдухан. При ее матери христианство уже распространилось в разных частях Грузии." },
  { key: "04-26", name: "Прмц. Марфы (Тестовой), инокини", kind: "saint", desc: "Преподобномученица Марфа родилась в 1883 году в деревне Арга Темниковского уезда Тамбовской губернии в семье крестьянина Тимофея Тестова. В 1914 году она поступила в Серафимо-Дивеевский монастырь Нижегородской губернии, где подвизалась ее родная сестра Пелагия [1] ." },
  { key: "04-27", name: "Свт. Мартина I, исп., папы Римского", kind: "saint", desc: "Святитель Мартин Исповедник, папа Римский, был уроженцем Тосканской области в Италии. Он получил хорошее образование и поступил в клир Римской Церкви. После смерти папы Феодора I (642–649) пресвитер Мартин был избран на престол." },
  { key: "04-27", name: "мч. Ардалиона", kind: "saint", desc: "Святой мученик Ардалион принял смерть за Христа при императоре Максимиане Галерии (305–311). Святой Ардалион был талантливым мимическим актером (&quot;из лицедеев&quot;)." },
  { key: "04-27", name: "Азата скопца", kind: "saint", desc: "Мученик Азат Персидский был евнухом, занимавшим высокое положение при царском дворе и пользовавшийся особенной любовью и уважением персидского царя Сапора." },
  { key: "04-27", name: "Св. Александра Орлова исп., пресвитера", kind: "saint", desc: "Священноисповедник Александр родился в 1878 году в селе Макковеево [1] Касимовского уезда Рязанской губернии в семье учителя Самыловской церковноприходской школы Василия Евдокимовича Орлова." },
  { key: "04-27", name: "Виленская", year: "1495", kind: "saint", desc: "Виленская икона Божией Матери написана святым евангелистом Лукой. Долгое время она была родовой святыней греческих императоров в Константинополе. В 1472 году икону перенесла в Москву София Палеолог, супруга великого князя Московского Иоанна III (1462–1505)." },
  { key: "04-27", name: "Остробрамская Виленская", kind: "saint", desc: "Сохранилось несколько преданий, повествующих об истории происхождения образа. Согласно одному из них, икона была принесена из Корсуни великим князем Ольгердом и подарена первой супруге Марии." },
  { key: "04-28", name: "Аристарха", kind: "saint", desc: "Св. апостол от 70-ти Аристарх упоминается св. апостолом Павлом в Послании к Колоссянам (Кол.4:10) и к Филимону (Флм.1:24). Св. апостол Аристарх сопутствовал апостолу Павлу, а впоследствии был поставлен епископом в сирийский город Апамею." },
  { key: "04-28", name: "Трофима", kind: "saint", desc: "Священномученик Трофим, апостол от 70-ти, был сподвижником апостола Павла. О нем упоминается в Деяниях апостолов и в Послании апостола Павла к Тимофею ( Деян.20:4,21:29 ; 2Тим.4:20 )." },
  { key: "04-28", name: "мч. Саввы Готфского", kind: "saint", desc: "Святой мученик Савва, по происхождению готф, жил в IV веке. В то время среди готфов проповедовал христианство епископ Вульфил. Среди многих крестившихся был и святой Савва." },
  { key: "04-28", name: "Сщмч. Александра Гневушева, пресвитера", kind: "saint", desc: "Священномученик Александр родился 23 сентября 1889 года в селе Русская Цильна Симбирского уезда Симбирской губернии в семье священника Федора Васильевича и его супруги Клавдии Николаевны Гневушевых." },
  { key: "04-29", name: "Сщмч. Константина Жданова, пресвитера", kind: "saint", desc: "Священномученик Константин (Константин Дмитриевич Жданов) родился 22 марта 1875 года в местечке Старо-Шарковщина Дисненского уезда Виленской губернии. Отец Константина – священник Димитрий Жданов – был сыном причетника." },
  { key: "04-29", name: "Ильинская (Черниговская)", year: "1658", kind: "saint", desc: "Ильинско-Черниговская икона Божией Матери была написана в 1658 году иконописцем Григорием Константиновичем Дубенским, в монашестве Геннадием. История создания иконы и чудеса от иконы описаны свидетелем событий святителем Димитрием, митропол" },
  { key: "04-29", name: "Тамбовская (Уткинская)", year: "1692", kind: "saint", desc: "В 1686 году святитель Питирим приехал в Тамбов и вместе с прочими святынями привёз список (копию) иконы Божией Матери, именуемой Ильинско-Черниговской, считающейся покровительницей Юго-Западного края." },
  { key: "04-30", name: "прп. Акакия, епископа Мелитинского", kind: "saint", desc: "Преподобный Акакий, епископ Мелитинский, родился в благочестивой семье в армянском городе Мелитина. Родители его долго были бездетными и, молясь о ребенке, обещали посвятить его Богу." },
  { key: "04-30", name: "прп. Зосимы, игумена Соловецкого", kind: "saint", desc: "Прп. Зосима Соловецкий (XV в.) вместе с прп. Германом поселился на пустынном острове около 1436 года, где основал Соловецкий монастырь. Став игуменом, ввел строгое общежитие, перенес на Соловки мощи прп." },
  { key: "04-30", name: "Обретение мощей прп. Александра Свирского, игумена", kind: "saint", desc: "Прп. Александр Свирский (1448–1533) ‒ великий русский святой, основатель Свято-Троицкого монастыря на реке Свири. Прославился аскетическими подвигами, прозорливостью и чудотворениями." },
  { key: "04-30", name: "прп. Паисия Киевского, Христа ради юродивого", kind: "saint", desc: "Преподобный Паисий, Христа ради юродивый (в миру Прокопий Григорьевич Яроцкий, 1821–1893), родился 8 июля 1821 года в городе Лубнах Полтавской губернии в многодетной и состоятельной семье мещан." },
  { key: "04-30", name: "мч. Адриана Коринфского", kind: "saint", desc: "Пострадал за Христа во время гонения на христиан в 251 году. За отказ принести жертву языческим богам и за разрушение языческого жертвенника святой Адриан был жестоко мучим, а потом сожжен в огромной печи." },
  { key: "04-30", name: "свт. Агапита I, папы Римского", kind: "saint", desc: "Святитель Агапит, папа Римский, был ревностным поборником православия. Своей благочестивой жизнью он заслужил всеобщее уважение и был возведен на папский престол в 535 году." },
  { key: "04-30", name: "Св. Михаила Новицкого исп., пресвитера", kind: "saint", desc: "Священноисповедник Михаил родился 26 июля 1889 года в Мозырском уезде Минской губернии в семье священника Константина и его супруги Стефаниды Новицких." },
  { key: "04-30", name: "сщмч. Феодора Недосекина, пресвитера", kind: "saint", desc: "Священномученик Феодор родился 10 ноября 1889 года в селе Новоселки Рославльского уезда Смоленской губернии в семье диакона Георгия Петровича Недосекина и его супруги Феодосии Петровны." },
];
